   p=os.path.join(root,f); lines=open(p,errors='ignore').read().splitlines()
   arrays={}
   for i,line in enumerate(lines):
    for m in re.finditer(r'(?:ut8|char)\s+(\w+)\s*\[(\d+)\]', line):
     arrays[m.group(1)]=int(m.group(2))
    if 'r_io_read_at' in line or 'r_io_nread_at' in line:
     block=line.strip()
     k=i+1
     while block.count('(')>block.count(')') and k<len(lines):
      block+=' '+lines[k].strip(); k+=1
     for name,size in arrays.items():
      if re.search(r'\b'+re.escape(name)+r'\b', block):
       print(f'{p}:{i+1}: {name}[{size}] {block}')
